<script>import'./styles/global.css';import{initTheme}from'./logic/theme.js';import{t,getDirection}from'./logic/i18n.js';import{getAuthState}from'./logic/auth.js';import{getMyProfile}from'./logic/db.js';import{HOME_PAGE,DEFAULT_LANGUAGE,LANGUAGES}from'./config.js';import Header from'./components/Header.svelte';import Sidebar from'./components/Sidebar.svelte';import WikiPage from'./components/WikiPage.svelte';import LocalEditor from'./components/LocalEditor.svelte';import LoginPage from'./components/LoginPage.svelte';import SettingsPage from'./components/SettingsPage.svelte';let lang=$state(DEFAULT_LANGUAGE);let route=$state('wiki');let slug=$state(HOME_PAGE);let edit=$state(false);let sq=$state('');let user=$state(null);let role=$state(null);let mobile=$state(typeof window!=='undefined'&&window.innerWidth<769);$effect(()=>{try{initTheme()}catch{}});$effect(()=>{document.documentElement.lang=lang;document.documentElement.dir=getDirection(lang);document.body.classList.toggle('ltr',lang==='en')});$effect(()=>{try{restoreAuth()}catch{}});async function restoreAuth(){try{const r=await getAuthState();if(r?.user){user=r.user;try{role=(await getMyProfile())?.role||'viewer'}catch{role='viewer'}}}catch{}}function rr(){let h=window.location.hash.slice(1)||`/${DEFAULT_LANGUAGE}/${HOME_PAGE}`;const[p,q]=h.split('?');const pr=new URLSearchParams(q||'');const parts=p.replace(/^\//,'').split('/');const isEdit=parts[0]==='edit';if(isEdit)parts.shift();let lfp=null;if(parts.length&&LANGUAGES.includes(parts[0]))lfp=parts.shift();if(lfp)lang=lfp;const f=parts[0];if(f==='login'){route='login';slug=f;edit=false}else if(f==='settings'){route='settings';slug=f;edit=false}else{route='wiki';slug=parts.join('/')||HOME_PAGE;edit=isEdit}const ql=pr.get('lang');if(ql==='en'||ql==='fa')lang=ql}$effect(()=>{window.addEventListener('hashchange',rr);rr();return()=>window.removeEventListener('hashchange',rr)});function nav(s){window.location.hash=`#/${lang}/${s}`}function go(rt){window.location.hash=`#/${lang}/${rt}`}function te(){window.location.hash=edit?`#/${lang}/${slug}`:`#/edit/${lang}/${slug}`}function hs(q){sq=q}const SK='emerald-wiki-sidebar';function gsi(){if(typeof window==='undefined')return false;if(window.innerWidth<769)return false;try{return localStorage.getItem(SK)==='open'}catch{return false}}let so=$state(gsi());function ss(v){if(typeof window!=='undefined'&&window.innerWidth>=769)try{localStorage.setItem(SK,v?'open':'closed')}catch{}}function ts(){so=!so;ss(so)}let _was=$state(mobile);$effect(()=>{function rs(){const m=window.innerWidth<769;if(m!==mobile)mobile=m;if(m&&!_was){so=false;ss(false)}_was=m}window.addEventListener('resize',rs);return()=>window.removeEventListener('resize',rs)});</script><div class="al"><Header {lang} {user} {role} currentRoute={route} currentSlug={slug} onToggleSidebar={ts} onSearch={hs} onNavigate={nav} onRoute={go}/><div class="ab">{#if route==='wiki'||route==='login'||route==='settings'}<Sidebar {lang} isOpen={so} currentSlug={slug} isMobile={mobile} onNavigate={nav} onToggle={ts}/>{/if}<main class="mc">{#if route==='wiki'&&user}<button class="fab" onclick={te} title={edit?'View':'Edit'}>{#if edit}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>{:else}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>{/if}</button>{/if}{#if route==='login'}<LoginPage {lang}/>{:else if route==='settings'}{#if user}<SettingsPage {lang} {user} {role}/>{:else}<div class="pe"><h2>{t(lang,'pageNotFound')}</h2><p><a href="#/{lang}/login">{t(lang,'login')}</a></p></div>{/if}{:else if edit&&user}<LocalEditor {slug} {lang}/>{:else if edit}<div class="pe"><h2>{t(lang,'pageNotFound')}</h2><p><a href="#/{lang}/login">{t(lang,'login')}</a></p></div>{:else}<WikiPage {slug} {lang}/>{/if}</main></div></div><style>.al{display:flex;flex-direction:column;height:100vh;overflow:hidden;background:var(--color-bg-secondary);transition:background var(--transition-normal)}.ab{display:flex;flex:1;width:100%;height:calc(100vh - var(--header-height));overflow:hidden}.mc{flex:1;min-width:0;display:flex;justify-content:flex-start;position:relative;overflow-y:auto;overflow-x:hidden}.pe{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:50vh;text-align:center;gap:1rem}.pe h2{color:var(--color-text-secondary);margin:0}.fab{position:fixed;bottom:1.5rem;left:1.5rem;z-index:80;width:48px;height:48px;border:none;border-radius:50%;background:var(--color-accent);color:var(--color-accent-text);box-shadow:var(--shadow-md);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all var(--transition-fast)}.fab:hover{background:var(--color-accent-dark);box-shadow:var(--shadow-lg);transform:scale(1.05)}@media(max-width:768px){.ab{flex-direction:column}}</style>